package gr.myworkstation.chat;

import android.content.ContentProvider;
import android.content.ContentValues;
import android.database.Cursor;
import android.net.Uri;
import android.os.ParcelFileDescriptor;
import java.io.FileNotFoundException;
import java.io.IOException;

/** Installed only in the instrumentation APK; streams generated bytes without files. */
public final class GalleryFixtureProvider extends ContentProvider {
    public static final String AUTHORITY = "gr.myworkstation.chat.preview.test.galleryfixture";
    @Override public boolean onCreate() { return true; }
    @Override public String getType(Uri uri) { return "image/jpeg"; }
    @Override public ParcelFileDescriptor openFile(Uri uri, String mode) throws FileNotFoundException {
        if (!"r".equals(mode) || !("/1".equals(uri.getPath()) || "/2".equals(uri.getPath()))) throw new FileNotFoundException();
        try {
            ParcelFileDescriptor[] pipe = ParcelFileDescriptor.createPipe();
            byte[] bytes = "/1".equals(uri.getPath()) ? new byte[]{1, 2} : new byte[]{3, 4};
            new Thread(() -> {
                try (ParcelFileDescriptor.AutoCloseOutputStream output = new ParcelFileDescriptor.AutoCloseOutputStream(pipe[1])) { output.write(bytes); }
                catch (IOException ignored) { }
            }, "isolated-gallery-fixture").start();
            return pipe[0];
        } catch (IOException failure) { throw new FileNotFoundException("Fixture pipe unavailable"); }
    }
    @Override public Cursor query(Uri uri, String[] projection, String selection, String[] args, String sort) { throw new UnsupportedOperationException(); }
    @Override public Uri insert(Uri uri, ContentValues values) { throw new UnsupportedOperationException(); }
    @Override public int delete(Uri uri, String selection, String[] args) { throw new UnsupportedOperationException(); }
    @Override public int update(Uri uri, ContentValues values, String selection, String[] args) { throw new UnsupportedOperationException(); }
}
